/**
 * workbench-program — a workbench whose monomers are GENERATED by a program
 * (expressiveness.plan.md E3, the `code` kind on mint_solid). The manifest stays
 * `kind: 'workbench'` and carries `program: { source, params, seed?, budgetMs? }` beside
 * any explicit monomer arrays; this module expands the program into monomers (or a face
 * list) so every downstream leg — the World, the studio shots, the skin scaffold, the
 * closure audit, the export ledger, the assembler's frozen parts — sees a plain workbench.
 *
 * The program runs in the code realm (polygonizer/code-realm.js) with toolkit v2 as `ctx`
 * and RETURNS either
 *   • a workbench spec — an object with monomer arrays (`lathes` / `extrudes` / `sweeps` /
 *     `lofts` / `fields` / `drapes` / `reliefs` / `shells` and/or an `assembly`), lowered by
 *     the kernel exactly as a hand-written spec (every validator, group tag, ledger line and
 *     engine leg inherited), merged BEFORE any explicit arrays on the manifest; or
 *   • a face list — an array of `{ corners:[[x,y,z]…], fill?, group? }` (the face-list
 *     currency); unlit faces are shaded here by their Newell normal; the closure audit says
 *     what it finds, advisory as always.
 * The return shape is detected, not declared.
 *
 * Expansion is deterministic in (source, params, seed), so it is memoised per process —
 * a render never pays the budget twice for the same recipe.
 */

import { runCodeRealm, validateProgram, sourceHash, REALM_VERSION, DEFAULT_BUDGET_MS, MAX_BUDGET_MS } from '../polygonizer/code-realm.js';
import { lowerAssembly } from '../polygonizer/workbench-assembly.js';
import { shadeHexMat, DEFAULT_LIGHT } from '../polygonizer/vexar.js';
import { buildBookToolkit } from '../views/recipe-book/toolkit.js';

export const MONOMER_KEYS = Object.freeze(['lathes', 'extrudes', 'sweeps', 'lofts', 'fields', 'drapes', 'reliefs', 'shells']);
const DEFAULT_TINT = '#9aa3b0';

const cache = new Map();
const MAX_CACHED = 32;
const cacheKey = (program) => `${sourceHash(program.source)}|${JSON.stringify(program.params ?? {})}|${Math.trunc(program.seed ?? 0) | 0}`;

export function hasProgram(manifest) {
  return !!(manifest && manifest.program && typeof manifest.program === 'object');
}

// Newell normal of a polygon → unit vector (z-up world, like every face lister)
function newellNormal(corners) {
  let nx = 0, ny = 0, nz = 0;
  for (let i = 0; i < corners.length; i += 1) {
    const [x0, y0, z0] = corners[i], [x1, y1, z1] = corners[(i + 1) % corners.length];
    nx += (y0 - y1) * (z0 + z1); ny += (z0 - z1) * (x0 + x1); nz += (x0 - x1) * (y0 + y1);
  }
  const l = Math.hypot(nx, ny, nz) || 1;
  return [nx / l, ny / l, nz / l];   // the face listers' `outNormal` shape (an array)
}

const isPoint = (c) => Array.isArray(c) && c.length >= 3 && c.slice(0, 3).every(Number.isFinite);

/** Face-list return path → baked faces (shaded, tagged). Throws a teaching error on a bad face. */
function facesFromProgram(list, light) {
  return list.map((f, i) => {
    if (!f || typeof f !== 'object' || !Array.isArray(f.corners) || f.corners.length < 3 || !f.corners.every(isPoint)) {
      throw new Error(`face[${i}]: a returned face is { corners:[[x,y,z] × ≥3], fill?, group? } — got ${JSON.stringify(f).slice(0, 80)}`);
    }
    const corners = f.corners.map((c) => [c[0], c[1], c[2]]);
    const n = newellNormal(corners);
    const fill = typeof f.fill === 'string' ? f.fill : shadeHexMat(typeof f.tint === 'string' ? f.tint : DEFAULT_TINT, n, null, { light: light || DEFAULT_LIGHT });
    return { corners, fill, doubleSided: true, outNormal: n, group: typeof f.group === 'string' ? f.group : 'program' };
  });
}

/**
 * expandWorkbenchProgram(manifest, { light }) →
 *   { manifest: <program-free workbench with the generated monomers merged in>,
 *     faces: <baked faces from a face-list return, or []>,
 *     program: { source_hash, realm_version, budget_ms, returned: 'spec'|'faces', ms, log, monomers|faces } }
 * Absent `program`, returns the manifest untouched (byte-for-byte: nothing else moves).
 * A program error rethrows with `.log` attached and the realm's message.
 */
export function expandWorkbenchProgram(manifest = {}, opts = {}) {
  if (!hasProgram(manifest)) return { manifest, faces: [], program: null };
  const { program, ...rest } = manifest;
  const errs = validateProgram(program);
  if (errs.length) throw new Error(`Invalid program:\n- ${errs.join('\n- ')}`);
  const key = cacheKey(program);
  let run = cache.get(key);
  if (!run) {
    const ctx = buildBookToolkit();
    let out;
    try {
      out = runCodeRealm({ source: program.source, params: program.params ?? {}, seed: program.seed ?? 0, budgetMs: program.budgetMs, ctx });
    } catch (err) {
      const e = new Error(`code program failed — ${err.message}${err.log && err.log.length ? `\nprogram log:\n  ${err.log.join('\n  ')}` : ''}`);
      e.log = err.log || [];
      e.timedOut = !!err.timedOut;
      throw e;
    }
    run = interpretReturn(out, program);
    if (cache.size >= MAX_CACHED) cache.delete(cache.keys().next().value);
    cache.set(key, run);
  }
  const merged = { ...rest };
  for (const k of MONOMER_KEYS) {
    const gen = run.spec[k] || [];
    const own = Array.isArray(rest[k]) ? rest[k] : [];
    if (gen.length || own.length) merged[k] = [...gen, ...own];
  }
  const faces = run.rawFaces.length ? facesFromProgram(run.rawFaces, opts.light) : [];
  return { manifest: merged, faces, program: run.report };
}

function interpretReturn({ value, log, ms }, program) {
  const base = { source_hash: sourceHash(program.source), realm_version: REALM_VERSION, budget_ms: Number.isFinite(program.budgetMs) ? Math.min(program.budgetMs, MAX_BUDGET_MS) : DEFAULT_BUDGET_MS, ms, log };
  if (Array.isArray(value)) {
    if (!value.length) throw withLog(new Error('code program returned an empty face list — return at least one face, or a spec with a monomer array'), log);
    return { spec: {}, rawFaces: value, report: { ...base, returned: 'faces', faces: value.length } };
  }
  if (value && typeof value === 'object') {
    const spec = {};
    let count = 0;
    if (value.assembly && typeof value.assembly === 'object') {
      const lowered = lowerAssembly(value.assembly);
      for (const k of ['lathes', 'extrudes', 'lofts', 'fields']) if (lowered[k] && lowered[k].length) { spec[k] = [...lowered[k]]; count += lowered[k].length; }
    }
    for (const k of MONOMER_KEYS) {
      if (Array.isArray(value[k]) && value[k].length) { spec[k] = [...(spec[k] || []), ...value[k]]; count += value[k].length; }
    }
    if (!count) {
      const keys = Object.keys(value);
      throw withLog(new Error(`code program returned an object with no monomer arrays (keys: ${keys.length ? keys.join(', ') : 'none'}) — return { lathes | extrudes | sweeps | lofts | fields | drapes | reliefs | shells | assembly } or a face list`), log);
    }
    return { spec, rawFaces: [], report: { ...base, returned: 'spec', monomers: count } };
  }
  throw withLog(new Error(`code program returned ${value === null ? 'nothing' : typeof value} — return a workbench spec object or a face list array`), log);
}

function withLog(err, log) { err.log = log; if (log && log.length) err.message += `\nprogram log:\n  ${log.join('\n  ')}`; return err; }

/** The program-free, monomer-merged manifest (what the ledger and the wrap collector read). */
export function expandedWorkbenchManifest(manifest) {
  return expandWorkbenchProgram(manifest).manifest;
}

/** Test seam. */
export function _resetWorkbenchProgramCache() { cache.clear(); }
